from __future__ import annotations

from identity_signals import (
    decide_match,
    group_consent_status,
    group_emails,
    group_household_keys,
    group_patient_ids,
    group_source_systems,
    same_household,
    same_strong_identifier,
    similar_first_name,
)
from profile_models import SourceProfile, UnifiedProfile, normalize_email, normalize_name


def _same_household(left: SourceProfile, right: SourceProfile) -> bool:
    return same_household(left, right)


def _similar_first_name(left: SourceProfile, right: SourceProfile) -> bool:
    return similar_first_name(left, right)


def _same_strong_identifier(left: SourceProfile, right: SourceProfile) -> bool:
    return same_strong_identifier(left, right)


def _should_merge(left: SourceProfile, right: SourceProfile) -> tuple[bool, str]:
    decision = decide_match(left, right)
    return decision.should_merge, decision.reason


def _unified_from_group(group: list[SourceProfile], index: int, reasons: list[str]) -> UnifiedProfile:
    primary = sorted(group, key=lambda profile: profile.source_id)[0]
    return UnifiedProfile(
        unified_id=f"unified-{index}",
        source_ids=tuple(profile.source_id for profile in group),
        first_name=primary.first_name,
        last_name=primary.last_name,
        emails=group_emails(group),
        patient_ids=group_patient_ids(group),
        consent_status=group_consent_status(group),
        merge_reasons=tuple(reasons),
        source_systems=group_source_systems(group),
        household_keys=group_household_keys(group),
    )


def _as_dict(profile: UnifiedProfile) -> dict[str, object]:
    return profile.as_dict()


def _warning(left: SourceProfile, right: SourceProfile) -> dict[str, object]:
    return {
        "source_id": right.source_id,
        "other_source_id": left.source_id,
        "warning": "household_identifier_conflict",
    }


def _profile_count_by_consent(unified_profiles: list[dict[str, object]]) -> dict[str, int]:
    counts = {"opted_in": 0, "opted_out": 0}
    for profile in unified_profiles:
        status = str(profile["consent_status"])
        if status in counts:
            counts[status] += 1
    return counts


def resolve_data_cloud_profiles(profiles: list[SourceProfile]) -> dict[str, object]:
    groups: list[list[SourceProfile]] = []
    group_reasons: list[list[str]] = []
    audit_warnings: list[dict[str, object]] = []

    for profile in profiles:
        matched_index: int | None = None
        matched_reason = ""
        for index, group in enumerate(groups):
            should_merge, reason = _should_merge(group[0], profile)
            if should_merge:
                matched_index = index
                matched_reason = reason
                break
            if reason == "identifier_conflict" and _same_household(group[0], profile):
                audit_warnings.append(_warning(group[0], profile))

        if matched_index is None:
            groups.append([profile])
            group_reasons.append(["single_source"])
        else:
            groups[matched_index].append(profile)
            group_reasons[matched_index].append(matched_reason)

    unified = [_as_dict(_unified_from_group(group, index + 1, group_reasons[index])) for index, group in enumerate(groups)]
    return summarize_identity_resolution(unified, audit_warnings)


def summarize_identity_resolution(
    unified_profiles: list[dict[str, object]],
    audit_warnings: list[dict[str, object]],
) -> dict[str, object]:
    return {
        "unified_profile_count": len(unified_profiles),
        "audit_warning_count": len(audit_warnings),
        "unified_profiles": unified_profiles,
        "audit_warnings": audit_warnings,
        "consent_counts": _profile_count_by_consent(unified_profiles),
    }


class DataCloudIdentityResolver:
    def resolve(self, profiles: list[SourceProfile]) -> dict[str, object]:
        return resolve_data_cloud_profiles(profiles)

    def preview_counts(self, profiles: list[SourceProfile]) -> dict[str, int]:
        result = self.resolve(profiles)
        return {
            "source_profile_count": len(profiles),
            "unified_profile_count": int(result["unified_profile_count"]),
            "audit_warning_count": int(result["audit_warning_count"]),
        }

