from __future__ import annotations

from profile_models import IdentityWarning, MatchDecision, SourceProfile, normalize_email, normalize_name, normalize_phone


def same_household(left: SourceProfile, right: SourceProfile) -> bool:
    same_address = left.address_id is not None and left.address_id == right.address_id
    same_phone = normalize_phone(left.phone) is not None and normalize_phone(left.phone) == normalize_phone(right.phone)
    same_household_id = left.household_id is not None and left.household_id == right.household_id
    same_last_name = normalize_name(left.last_name) == normalize_name(right.last_name)
    return same_last_name and (same_address or same_phone or same_household_id)


def similar_first_name(left: SourceProfile, right: SourceProfile) -> bool:
    left_name = normalize_name(left.first_name)
    right_name = normalize_name(right.first_name)
    return bool(left_name and right_name and left_name[0] == right_name[0])


def same_strong_identifier(left: SourceProfile, right: SourceProfile) -> bool:
    left_email = normalize_email(left.email)
    right_email = normalize_email(right.email)
    if left.patient_id is not None and left.patient_id == right.patient_id:
        return True
    if left_email is not None and left_email == right_email:
        return True
    return False


def conflicting_patient_ids(left: SourceProfile, right: SourceProfile) -> bool:
    return left.patient_id is not None and right.patient_id is not None and left.patient_id != right.patient_id


def conflicting_emails(left: SourceProfile, right: SourceProfile) -> bool:
    left_email = normalize_email(left.email)
    right_email = normalize_email(right.email)
    return left_email is not None and right_email is not None and left_email != right_email


def strong_identifier_conflict(left: SourceProfile, right: SourceProfile) -> bool:
    return conflicting_patient_ids(left, right) or conflicting_emails(left, right)


def household_conflict_warning(left: SourceProfile, right: SourceProfile) -> IdentityWarning:
    return IdentityWarning(
        source_id=right.source_id,
        other_source_id=left.source_id,
        warning="household_identifier_conflict",
        detail="shared_household_with_conflicting_identifier",
    )


def decide_match(left: SourceProfile, right: SourceProfile) -> MatchDecision:
    if same_strong_identifier(left, right):
        return MatchDecision(True, "strong_identifier_match")
    if same_household(left, right) and similar_first_name(left, right):
        return MatchDecision(True, "household_soft_match")
    if same_household(left, right):
        return MatchDecision(False, "identifier_conflict", household_conflict_warning(left, right))
    return MatchDecision(False, "identifier_conflict")


def group_consent_status(profiles: list[SourceProfile]) -> str:
    return "opted_out" if any(profile.consent_status == "opted_out" for profile in profiles) else "opted_in"


def group_emails(profiles: list[SourceProfile]) -> tuple[str, ...]:
    return tuple(sorted({email for profile in profiles if (email := normalize_email(profile.email)) is not None}))


def group_patient_ids(profiles: list[SourceProfile]) -> tuple[str, ...]:
    return tuple(sorted({profile.patient_id for profile in profiles if profile.patient_id is not None}))


def group_source_systems(profiles: list[SourceProfile]) -> tuple[str, ...]:
    return tuple(sorted({profile.source_system for profile in profiles}))


def group_household_keys(profiles: list[SourceProfile]) -> tuple[str, ...]:
    keys: set[str] = set()
    for profile in profiles:
        keys.update(profile.household_keys())
    return tuple(sorted(keys))


class IdentitySignalEvaluator:
    def decide(self, left: SourceProfile, right: SourceProfile) -> MatchDecision:
        return decide_match(left, right)

    def risky_household_pair(self, left: SourceProfile, right: SourceProfile) -> bool:
        return same_household(left, right) and strong_identifier_conflict(left, right)

    def warning_for(self, left: SourceProfile, right: SourceProfile) -> dict[str, object] | None:
        if not self.risky_household_pair(left, right):
            return None
        return household_conflict_warning(left, right).as_dict()

