from __future__ import annotations

from dataclasses import dataclass


VALID_CONSENT_STATUSES = {"opted_in", "opted_out"}
VALID_SOURCE_SYSTEMS = {"ServiceCloud", "MarketingCloud", "DataCloud", "EHR", "InsuranceFeed", "AppointmentSystem"}


def _require_text(value: str, field_name: str) -> None:
    if not value.strip():
        raise ValueError(f"{field_name} required")


@dataclass(frozen=True)
class SourceProfile:
    source_id: str
    source_system: str
    first_name: str
    last_name: str
    email: str | None
    phone: str | None
    address_id: str | None
    patient_id: str | None
    consent_status: str
    date_of_birth: str | None = None
    household_id: str | None = None
    last_updated_minute: int = 0

    def __post_init__(self) -> None:
        _require_text(self.source_id, "source_id")
        _require_text(self.source_system, "source_system")
        _require_text(self.first_name, "first_name")
        _require_text(self.last_name, "last_name")
        if self.email is not None and "@" not in self.email:
            raise ValueError("email must be valid")
        if self.consent_status not in VALID_CONSENT_STATUSES:
            raise ValueError("consent_status must be opted_in or opted_out")
        if self.phone is not None:
            _require_text(self.phone, "phone")
        if self.address_id is not None:
            _require_text(self.address_id, "address_id")
        if self.patient_id is not None:
            _require_text(self.patient_id, "patient_id")
        if self.date_of_birth is not None:
            _require_text(self.date_of_birth, "date_of_birth")
        if self.household_id is not None:
            _require_text(self.household_id, "household_id")
        if self.last_updated_minute < 0:
            raise ValueError("last_updated_minute must be non-negative")

    def strong_ids(self) -> dict[str, str]:
        ids: dict[str, str] = {}
        if self.patient_id is not None:
            ids["patient_id"] = self.patient_id
        normalized = normalize_email(self.email)
        if normalized is not None:
            ids["email"] = normalized
        return ids

    def household_keys(self) -> tuple[str, ...]:
        keys: list[str] = []
        if self.address_id is not None:
            keys.append(f"address:{self.address_id}")
        if self.phone is not None:
            keys.append(f"phone:{self.phone}")
        if self.household_id is not None:
            keys.append(f"household:{self.household_id}")
        return tuple(keys)


@dataclass(frozen=True)
class UnifiedProfile:
    unified_id: str
    source_ids: tuple[str, ...]
    first_name: str
    last_name: str
    emails: tuple[str, ...]
    patient_ids: tuple[str, ...]
    consent_status: str
    merge_reasons: tuple[str, ...]
    source_systems: tuple[str, ...] = ()
    household_keys: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        _require_text(self.unified_id, "unified_id")
        if not self.source_ids:
            raise ValueError("source_ids required")
        _require_text(self.first_name, "first_name")
        _require_text(self.last_name, "last_name")
        if self.consent_status not in VALID_CONSENT_STATUSES:
            raise ValueError("consent_status must be opted_in or opted_out")
        for source_id in self.source_ids:
            _require_text(source_id, "source_id")
        for email in self.emails:
            if "@" not in email:
                raise ValueError("email must be valid")
        for patient_id in self.patient_ids:
            _require_text(patient_id, "patient_id")
        for reason in self.merge_reasons:
            _require_text(reason, "merge_reason")

    def as_dict(self) -> dict[str, object]:
        return {
            "unified_id": self.unified_id,
            "source_ids": list(self.source_ids),
            "first_name": self.first_name,
            "last_name": self.last_name,
            "emails": list(self.emails),
            "patient_ids": list(self.patient_ids),
            "consent_status": self.consent_status,
            "merge_reasons": list(self.merge_reasons),
            "source_systems": list(self.source_systems),
            "household_keys": list(self.household_keys),
        }


@dataclass(frozen=True)
class IdentityWarning:
    source_id: str
    other_source_id: str
    warning: str
    detail: str = "manual_review"

    def __post_init__(self) -> None:
        _require_text(self.source_id, "source_id")
        _require_text(self.other_source_id, "other_source_id")
        _require_text(self.warning, "warning")
        _require_text(self.detail, "detail")

    def as_dict(self) -> dict[str, object]:
        return {
            "source_id": self.source_id,
            "other_source_id": self.other_source_id,
            "warning": self.warning,
            "detail": self.detail,
        }


@dataclass(frozen=True)
class MatchDecision:
    should_merge: bool
    reason: str
    warning: IdentityWarning | None = None

    def __post_init__(self) -> None:
        _require_text(self.reason, "reason")


def normalize_email(email: str | None) -> str | None:
    if email is None:
        return None
    return email.strip().lower()


def normalize_name(name: str) -> str:
    return name.strip().lower()


def normalize_phone(phone: str | None) -> str | None:
    if phone is None:
        return None
    digits = "".join(character for character in phone if character.isdigit())
    return digits or None

