            raise ValueError("source_ids required")
        _require_text(self.first_name, "first_name")
        _require_text(self.last_name, "last_name")
        if self.consent_status not in VALID_CONSENT_STATUSES:
            raise ValueError("consent_status must be opted_in or opted_out")
        for source_id in self.source_ids:
            _require_text(source_id, "source_id")
        for email in self.emails:
            if "@" not in email:
                raise ValueError("email must be valid")
        for patient_id in self.patient_ids:
            _require_text(patient_id, "patient_id")
        for reason in self.merge_reasons:
            _require_text(reason, "merge_reason")

    def as_dict(self) -> dict[str, object]:
        return {
            "unified_id": self.unified_id,
            "source_ids": list(self.source_ids),
            "first_name": self.first_name,
            "last_name": self.last_name,
            "emails": list(self.emails),
            "patient_ids": list(self.patient_ids),
            "consent_status": self.consent_status,
            "merge_reasons": list(self.merge_reasons),
            "source_systems": list(self.source_systems),
            "household_keys": list(self.household_keys),
        }


